static void receive_packet(node_t *n, vpn_packet_t *packet) { /* <=== receive_packet */ 
	ifdebug(TRAFFIC) logger(LOG_DEBUG, "Received packet of %d bytes from %s (%s)",
			   packet->len, n->name, n->hostname);

	route(n, packet);
}

void logger(int priority, const char *format, ...) { /* <=== logger */ 
	va_list ap;
	char timestr[32] = "";
	time_t now;

	va_start(ap, format);

	switch(logmode) {
		case LOGMODE_STDERR:
			vfprintf(stderr, format, ap);
			fprintf(stderr, "\n");
			fflush(stderr);
			break;
		case LOGMODE_FILE:
			now = time(NULL);
			strftime(timestr, sizeof timestr, "%Y-%m-%d %H:%M:%S", localtime(&now));
			fprintf(logfile, "%s %s[%ld]: ", timestr, logident, (long)logpid);
			vfprintf(logfile, format, ap);
			fprintf(logfile, "\n");
			fflush(logfile);
			break;
		case LOGMODE_SYSLOG:
#ifdef HAVE_MINGW
			{
				char message[4096];
				const char *messages[] = {message};
				vsnprintf(message, sizeof(message), format, ap);
				ReportEvent(loghandle, priority, 0, 0, NULL, 1, 0, messages, NULL);
			}
#else
#ifdef HAVE_SYSLOG_H
#ifdef HAVE_VSYSLOG
			vsyslog(priority, format, ap);
#else
			{
				char message[4096];
				vsnprintf(message, sizeof(message), format, ap);
				syslog(priority, "%s", message);
			}
#endif
			break;
#endif
#endif
		case LOGMODE_NULL:
			break;
	}

	va_end(ap);
}

void send_packet(const node_t *n, vpn_packet_t *packet) { /* <=== send_packet */ 
	node_t *via;

	if(n == myself) {
		if(overwrite_mac)
			 memcpy(packet->data, mymac.x, ETH_ALEN);
		devops.write(packet);
		return;
	}

	ifdebug(TRAFFIC) logger(LOG_ERR, "Sending packet of %d bytes to %s (%s)",
			   packet->len, n->name, n->hostname);

	if(!n->status.reachable) {
		ifdebug(TRAFFIC) logger(LOG_INFO, "Node %s (%s) is not reachable",
				   n->name, n->hostname);
		return;
	}

	via = (packet->priority == -1 || n->via == myself) ? n->nexthop : n->via;

	if(via != n)
		ifdebug(TRAFFIC) logger(LOG_INFO, "Sending packet to %s via %s (%s)",
			   n->name, via->name, n->via->hostname);

	if(packet->priority == -1 || ((myself->options | via->options) & OPTION_TCPONLY)) {
		if(!send_tcppacket(via->connection, packet))
			terminate_connection(via->connection, true);
	} else
		send_udppacket(via, packet);
}

static void route_ipv4(node_t *source, vpn_packet_t *packet) { /* <=== route_ipv4 */ 
	if(!checklength(source, packet, ether_size + ip_size))
		return;

	if(broadcast_mode && (((packet->data[30] & 0xf0) == 0xe0) || (
			packet->data[30] == 255 &&
			packet->data[31] == 255 &&
			packet->data[32] == 255 &&
			packet->data[33] == 255)))
		broadcast_packet(source, packet);
	else
		route_ipv4_unicast(source, packet);
}

static bool checklength(node_t *source, vpn_packet_t *packet, length_t length) { /* <=== checklength */ 
	if(packet->len < length) {
		ifdebug(TRAFFIC) logger(LOG_WARNING, "Got too short packet from %s (%s)", source->name, source->hostname);
		return false;
	} else
		return true;
}

void route(node_t *source, vpn_packet_t *packet) { /* <=== route */ 
	if(forwarding_mode == FMODE_KERNEL && source != myself) {
		send_packet(myself, packet);
		return;
	}

	if(!checklength(source, packet, ether_size))
		return;

	if(decrement_ttl && source != myself)
		if(!do_decrement_ttl(source, packet))
			return;

	switch (routing_mode) {
		case RMODE_ROUTER:
			{
				uint16_t type = packet->data[12] << 8 | packet->data[13];

				switch (type) {
					case ETH_P_ARP:
						route_arp(source, packet);
						break;

					case ETH_P_IP:
						route_ipv4(source, packet);
						break;

					case ETH_P_IPV6:
						route_ipv6(source, packet);
						break;

					default:
						ifdebug(TRAFFIC) logger(LOG_WARNING, "Cannot route packet from %s (%s): unknown type %hx", source->name, source->hostname, type);
						break;
				}
			}
			break;

		case RMODE_SWITCH:
			route_mac(source, packet);
			break;

		case RMODE_HUB:
			broadcast_packet(source, packet);
			break;
	}
}

static void route_arp(node_t *source, vpn_packet_t *packet) { /* <=== route_arp */ 
	struct ether_arp arp;
	subnet_t *subnet;
	struct in_addr addr;

	if(!checklength(source, packet, ether_size + arp_size))
		return;

	if(source != myself) {
		ifdebug(TRAFFIC) logger(LOG_WARNING, "Got ARP request from %s (%s) while in router mode!", source->name, source->hostname);
		return;
	}

	/* First, snatch the source address from the ARP packet */

	if(overwrite_mac)
		memcpy(mymac.x, packet->data + ETH_ALEN, ETH_ALEN);

	/* Copy headers from packet to structs on the stack */

	memcpy(&arp, packet->data + ether_size, arp_size);

	/* Check if this is a valid ARP request */

	if(ntohs(arp.arp_hrd) != ARPHRD_ETHER || ntohs(arp.arp_pro) != ETH_P_IP ||
	   arp.arp_hln != ETH_ALEN || arp.arp_pln != sizeof(addr) || ntohs(arp.arp_op) != ARPOP_REQUEST) {
		ifdebug(TRAFFIC) logger(LOG_WARNING, "Cannot route packet: received unknown type ARP request");
		return;
	}

	/* Check if the IPv4 address exists on the VPN */

	subnet = lookup_subnet_ipv4((ipv4_t *) &arp.arp_tpa);

	if(!subnet) {
		ifdebug(TRAFFIC) logger(LOG_WARNING, "Cannot route packet: ARP request for unknown address %d.%d.%d.%d",
				   arp.arp_tpa[0], arp.arp_tpa[1], arp.arp_tpa[2],
				   arp.arp_tpa[3]);
		return;
	}

	/* Check if it is for our own subnet */

	if(subnet->owner == myself)
		return;					/* silently ignore */

	memcpy(packet->data, packet->data + ETH_ALEN, ETH_ALEN);	/* copy destination address */
	packet->data[ETH_ALEN * 2 - 1] ^= 0xFF;	/* mangle source address so it looks like it's not from us */

	memcpy(&addr, arp.arp_tpa, sizeof(addr));	/* save protocol addr */
	memcpy(arp.arp_tpa, arp.arp_spa, sizeof(addr));	/* swap destination and source protocol address */
	memcpy(arp.arp_spa, &addr, sizeof(addr));	/* ... */

	memcpy(arp.arp_tha, arp.arp_sha, ETH_ALEN);	/* set target hard/proto addr */
	memcpy(arp.arp_sha, packet->data + ETH_ALEN, ETH_ALEN);	/* add fake source hard addr */
	arp.arp_op = htons(ARPOP_REPLY);

	/* Copy structs on stack back to packet */

	memcpy(packet->data + ether_size, &arp, arp_size);

	send_packet(source, packet);
}

static bool do_decrement_ttl(node_t *source, vpn_packet_t *packet) { /* <=== do_decrement_ttl */ 
	uint16_t type = packet->data[12] << 8 | packet->data[13];
	length_t ethlen = ether_size;

	if(type == ETH_P_8021Q) {
		type = packet->data[16] << 8 | packet->data[17];
		ethlen += 4;
	}

	switch (type) {
		case ETH_P_IP:
			if(!checklength(source, packet, ethlen + ip_size))
				return false;

			if(packet->data[ethlen + 8] < 1) {
				if(packet->data[ethlen + 11] != IPPROTO_ICMP || packet->data[ethlen + 32] != ICMP_TIME_EXCEEDED)
					route_ipv4_unreachable(source, packet, ethlen, ICMP_TIME_EXCEEDED, ICMP_EXC_TTL);
				return false;
			}

			uint16_t old = packet->data[ethlen + 8] << 8 | packet->data[ethlen + 9];
			packet->data[ethlen + 8]--;
			uint16_t new = packet->data[ethlen + 8] << 8 | packet->data[ethlen + 9];

			uint32_t checksum = packet->data[ethlen + 10] << 8 | packet->data[ethlen + 11];
			checksum += old + (~new & 0xFFFF);
			while(checksum >> 16)
				checksum = (checksum & 0xFFFF) + (checksum >> 16);
			packet->data[ethlen + 10] = checksum >> 8;
			packet->data[ethlen + 11] = checksum & 0xff;

			return true;

		case ETH_P_IPV6:
			if(!checklength(source, packet, ethlen + ip6_size))
				return false;

			if(packet->data[ethlen + 7] < 1) {
				if(packet->data[ethlen + 6] != IPPROTO_ICMPV6 || packet->data[ethlen + 40] != ICMP6_TIME_EXCEEDED)
					route_ipv6_unreachable(source, packet, ethlen, ICMP6_TIME_EXCEEDED, ICMP6_TIME_EXCEED_TRANSIT);
				return false;
			}

			packet->data[ethlen + 7]--;

			return true;

		default:
			return true;
	}
}

void broadcast_packet(const node_t *from, vpn_packet_t *packet) { /* <=== broadcast_packet */ 
	avl_node_t *node;
	connection_t *c;
	node_t *n;

	// Always give ourself a copy of the packet.
	if(from != myself)
		send_packet(myself, packet);

	// In TunnelServer mode, do not forward broadcast packets.
        // The MST might not be valid and create loops.
	if(tunnelserver || broadcast_mode == BMODE_NONE)
		return;

	ifdebug(TRAFFIC) logger(LOG_INFO, "Broadcasting packet of %d bytes from %s (%s)",
			   packet->len, from->name, from->hostname);

	switch(broadcast_mode) {
		// In MST mode, broadcast packets travel via the Minimum Spanning Tree.
		// This guarantees all nodes receive the broadcast packet, and
		// usually distributes the sending of broadcast packets over all nodes.
		case BMODE_MST:
			for(node = connection_tree->head; node; node = node->next) {
				c = node->data;

				if(c->status.active && c->status.mst && c != from->nexthop->connection)
					send_packet(c->node, packet);
			}
			break;

		// In direct mode, we send copies to each node we know of.
	        // However, this only reaches nodes that can be reached in a single hop.
		// We don't have enough information to forward broadcast packets in this case.
		case BMODE_DIRECT:
			if(from != myself)
				break;

			for(node = node_udp_tree->head; node; node = node->next) {
				n = node->data;

				if(n->status.reachable && ((n->via == myself && n->nexthop == n) || n->via == n))
					send_packet(n, packet);
			}
			break;

		default:
			break;
	}
}

static void route_mac(node_t *source, vpn_packet_t *packet) { /* <=== route_mac */ 
	subnet_t *subnet;
	mac_t dest;

	/* Learn source address */

	if(source == myself) {
		mac_t src;
		memcpy(&src, &packet->data[6], sizeof src);
		learn_mac(&src);
	}

	/* Lookup destination address */

	memcpy(&dest, &packet->data[0], sizeof dest);
	subnet = lookup_subnet_mac(NULL, &dest);

	if(!subnet) {
		broadcast_packet(source, packet);
		return;
	}

	if(subnet->owner == source) {
		ifdebug(TRAFFIC) logger(LOG_WARNING, "Packet looping back to %s (%s)!", source->name, source->hostname);
		return;
	}

	if(forwarding_mode == FMODE_OFF && source != myself && subnet->owner != myself)
		return;

	uint16_t type = packet->data[12] << 8 | packet->data[13];

	if(priorityinheritance && type == ETH_P_IP && packet->len >= ether_size + ip_size)
		packet->priority = packet->data[15];

	// Handle packets larger than PMTU

	node_t *via = (subnet->owner->via == myself) ? subnet->owner->nexthop : subnet->owner->via;

	if(directonly && subnet->owner != via)
		return;

	if(via && packet->len > via->mtu && via != myself) {
		ifdebug(TRAFFIC) logger(LOG_INFO, "Packet for %s (%s) length %d larger than MTU %d", subnet->owner->name, subnet->owner->hostname, packet->len, via->mtu);
		length_t ethlen = 14;

		if(type == ETH_P_8021Q) {
			type = packet->data[16] << 8 | packet->data[17];
			ethlen += 4;
		}

		if(type == ETH_P_IP && packet->len > 576 + ethlen) {
			if(packet->data[6 + ethlen] & 0x40) {
				packet->len = via->mtu;
				route_ipv4_unreachable(source, packet, ethlen, ICMP_DEST_UNREACH, ICMP_FRAG_NEEDED);
			} else {
				fragment_ipv4_packet(via, packet, ethlen);
			}
			return;
		} else if(type == ETH_P_IPV6 && packet->len > 1280 + ethlen) {
			packet->len = via->mtu;
			route_ipv6_unreachable(source, packet, ethlen, ICMP6_PACKET_TOO_BIG, 0);
			return;
		}
	}

	clamp_mss(source, via, packet);

	send_packet(subnet->owner, packet);
}

static void route_ipv6(node_t *source, vpn_packet_t *packet) { /* <=== route_ipv6 */ 
	if(!checklength(source, packet, ether_size + ip6_size))
		return;

	if(packet->data[20] == IPPROTO_ICMPV6 && checklength(source, packet, ether_size + ip6_size + icmp6_size) && packet->data[54] == ND_NEIGHBOR_SOLICIT) {
		route_neighborsol(source, packet);
		return;
	}

	if(broadcast_mode && packet->data[38] == 255)
		broadcast_packet(source, packet);
	else
		route_ipv6_unicast(source, packet);
}

typeDefs:
typedef struct vpn_packet_t {
	length_t len;				/* the actual number of bytes in the `data' field */
	int priority;				/* priority or TOS */
	uint32_t seqno;				/* 32 bits sequence number (network byte order of course) */
	uint8_t data[MAXSIZE];
} vpn_packet_t;

vulnerableMethods_after:
void receive_tcppacket(connection_t *c, const char *buffer, int len) { /* <=== receive_tcppacket */ 
	vpn_packet_t outpkt;

	if(len > sizeof outpkt.data)
		return;

	outpkt.len = len;
	if(c->options & OPTION_TCPONLY)
		outpkt.priority = 0;
	else
		outpkt.priority = -1;
	memcpy(outpkt.data, buffer, len);

	receive_packet(c->node, &outpkt);
}

